<?php use App\Core\Csrf;use App\Core\Util;?>
<div class="page-head"><div><div class="eyebrow">Administrator</div><h1>Daily Work Progress</h1></div><form class="filters"><input type="date" name="date" value="<?=Util::e($date)?>"><button class="btn">View</button></form></div>
<div class="panel"><div class="panel-head"><h2>Posts — <?=Util::e($date)?></h2><a class="btn" href="<?=$config['app']['base_path']?>/admin/reports">Weekly / Monthly Reports</a></div>
<div class="tablewrap"><table><tr><th>Sales</th><th>Platform</th><th>Title</th><th>Published</th><th>Status</th><th></th></tr><?php foreach($posts as$p):?><tr><td><?=Util::e($p['display_name'])?><small>#<?=Util::e($p['sales_id'])?></small></td><td><?=Util::e(ucfirst($p['platform']))?></td><td><?=Util::e($p['title'])?></td><td><?=Util::e($p['published_at'])?></td><td><?php if(in_array(($p['admin_review_status']??null),['good','bad'],true)):?><span class="status <?=Util::e($p['admin_review_status'])?>"><?=Util::e(ucfirst($p['admin_review_status']))?></span><?php else:?>—<?php endif;?></td><td><a href="<?=$config['app']['base_path']?>/admin/post?id=<?=(int)$p['id']?>">Review</a></td></tr><?php endforeach;?></table></div></div>
<div class="panel"><h2>Daily Sales Reviews</h2><div class="sales-grid"><?php foreach($sales as$s):?><a class="sales-card" href="<?=$config['app']['base_path']?>/admin/daily?sales_id=<?=(int)$s['id']?>&date=<?=Util::e($date)?>"><b><?=Util::e($s['display_name'])?></b><span>#<?=Util::e($s['sales_id'])?></span><em>Review day →</em></a><?php endforeach;?></div></div>
<?php if($deletionRequests):?><div class="panel"><h2>Deletion Requests</h2><?php foreach($deletionRequests as$r):?><div class="request"><div><b><?=Util::e($r['display_name'])?> — <?=Util::e($r['title'])?></b><span><?=Util::e($r['reason'])?></span></div><form method="post" action="<?=$config['app']['base_path']?>/admin/delete-request"><input type="hidden" name="_csrf" value="<?=Util::e(Csrf::token())?>"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><button name="action" value="approve" class="tiny okbtn">Approve delete</button><button name="action" value="reject" class="tiny badbtn">Reject</button></form></div><?php endforeach;?></div><?php endif;?>
